-- Persist the component-library taxonomy and supplier source used by both library trees.
-- Categories are global taxonomy nodes with explicit parent-child hierarchy.
-- Suppliers and component rows remain workspace scoped.

create table if not exists public.component_category_nodes (
  id text primary key,
  parent_id text references public.component_category_nodes(id) on delete cascade,
  label text not null check (char_length(trim(label)) > 0),
  node_type text not null check (node_type in ('organizer', 'category', 'subcategory')),
  sort_order integer not null default 0,
  code text,
  metadata jsonb not null default '{}'::jsonb,
  created_by uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.component_suppliers (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references public.workspaces(id) on delete cascade,
  name text not null check (char_length(trim(name)) > 0),
  normalized_name text not null check (char_length(trim(normalized_name)) > 0),
  sort_order integer not null default 0,
  metadata jsonb not null default '{}'::jsonb,
  created_by uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint component_suppliers_workspace_normalized_name_key unique (workspace_id, normalized_name)
);

alter table public.cost_library_items
  add column if not exists category_node_id text references public.component_category_nodes(id) on delete set null,
  add column if not exists supplier_id uuid references public.component_suppliers(id) on delete set null;

alter table public.estimate_row_items
  add column if not exists category_node_id text references public.component_category_nodes(id) on delete set null,
  add column if not exists supplier_id uuid references public.component_suppliers(id) on delete set null;

create index if not exists component_category_nodes_parent_sort_idx on public.component_category_nodes(parent_id, sort_order);
create index if not exists component_suppliers_workspace_sort_idx on public.component_suppliers(workspace_id, sort_order, name);
create index if not exists cost_library_items_category_node_id_idx on public.cost_library_items(category_node_id);
create index if not exists cost_library_items_supplier_id_idx on public.cost_library_items(supplier_id);
create index if not exists estimate_row_items_category_node_id_idx on public.estimate_row_items(category_node_id);
create index if not exists estimate_row_items_supplier_id_idx on public.estimate_row_items(supplier_id);

drop trigger if exists component_category_nodes_set_updated_at on public.component_category_nodes;
drop trigger if exists component_suppliers_set_updated_at on public.component_suppliers;

create trigger component_category_nodes_set_updated_at before update on public.component_category_nodes for each row execute function public.set_updated_at();
create trigger component_suppliers_set_updated_at before update on public.component_suppliers for each row execute function public.set_updated_at();

alter table public.component_category_nodes enable row level security;
alter table public.component_suppliers enable row level security;

drop policy if exists "authenticated users can view component categories" on public.component_category_nodes;
drop policy if exists "workspace admins can manage component categories" on public.component_category_nodes;
drop policy if exists "members can manage component suppliers" on public.component_suppliers;

create policy "authenticated users can view component categories" on public.component_category_nodes
  for select to authenticated using (true);

create policy "workspace admins can manage component categories" on public.component_category_nodes
  for all to authenticated using (
    exists (
      select 1 from public.profiles p
      where p.id = auth.uid()
        and p.role in ('ceo', 'admin')
    )
  ) with check (
    exists (
      select 1 from public.profiles p
      where p.id = auth.uid()
        and p.role in ('ceo', 'admin')
    )
  );

create policy "members can manage component suppliers" on public.component_suppliers
  for all to authenticated using (public.is_workspace_member(workspace_id)) with check (public.is_workspace_member(workspace_id));

