":"6e5a9638-a6fb-b92d-2320-c708bf13a302","originalId":"lib-wood-plastic-composite-deck","sourceId":"lib-wood-plastic-composite-deck","name":"Wood-Plastic Composite Decking Board","description":"WPC decking allowance for balconies, roof decks, and outdoor lounge areas; confirm board profile, clips, subframe, UV warranty, and drainage.","category":"Hardscape","categoryNodeId":"landscape-hardscape","supplier":"Wilcon Depot / PH outdoor decking suppliers","supplierKey":"wilcon-depot-ph-outdoor-decking-suppliers","kind":"material","unit":"sqm","unitCost":3600,"miscCost":900,"pricingSource":"Philippine WPC decking supplier allowance — verify system quote","pricingDate":"2026-05-18","confidence":"Demo seed","thumbnailPath":"/component-thumbnails/lib-wood-plastic-composite-deck.jpg","metadata":{"seeded":true,"seedVersion":"2026-05-22-component-library-taxonomy-source","sourceFixtureId":"lib-wood-plastic-composite-deck","source":"supplier","categoryNodeId":"landscape-hardscape","categoryPath":["Site","Landscape","Hardscape"],"supplierKey":"wilcon-depot-ph-outdoor-decking-suppliers","tags":["flooring","decking","wpc","outdoor"],"discipline":"Architectural","designation":"Floor / Deck Finish","sourceUrl":"https://www.wilcon.com.ph/","notes":null,"imageUrl":"/component-thumbnails/lib-wood-plastic-composite-deck.jpg"}}]'::jsonb) as item(
    id uuid,
    "originalId" text,
    "sourceId" text,
    name text,
    description text,
    category text,
    "categoryNodeId" text,
    supplier text,
    "supplierKey" text,
    kind public.cost_library_item_kind,
    unit text,
    "unitCost" numeric,
    "miscCost" numeric,
    "pricingSource" text,
    "pricingDate" date,
    confidence text,
    "thumbnailPath" text,
    metadata jsonb
  )
), supplier_seed as (
  select distinct w.id as workspace_id, item.supplier, item."supplierKey", item.metadata ->> 'seedVersion' as seed_version
  from public.workspaces w
  cross join seed_items item
  union
  select distinct cli.workspace_id,
    coalesce(nullif(trim(cli.supplier), ''), 'Manual / no supplier') as supplier,
    coalesce(nullif(regexp_replace(lower(trim(cli.supplier)), '[^a-z0-9]+', '-', 'g'), ''), 'manual-no-supplier') as "supplierKey",
    '2026-05-22-component-library-taxonomy-source' as seed_version
  from public.cost_library_items cli
  union
  select distinct p.workspace_id,
    coalesce(nullif(trim(eri.supplier), ''), 'Manual / no supplier') as supplier,
    coalesce(nullif(regexp_replace(lower(trim(eri.supplier)), '[^a-z0-9]+', '-', 'g'), ''), 'manual-no-supplier') as "supplierKey",
    '2026-05-22-component-library-taxonomy-source' as seed_version
  from public.estimate_row_items eri
  join public.estimates e on e.id = eri.estimate_id
  join public.projects p on p.id = e.project_id
)
insert into public.component_suppliers (workspace_id, name, normalized_name, metadata)
select workspace_id,
  supplier,
  "supplierKey",
  jsonb_build_object('seeded', true, 'seedVersion', seed_version)
from supplier_seed
on conflict (workspace_id, normalized_name) do update
  set name = excluded.name,
      metadata = public.component_suppliers.metadata || excluded.metadata;

