":"6e5a9638-a6fb-b92d-2320-c708bf13a302","originalId":"lib-wood-plastic-composite-deck","sourceId":"lib-wood-plastic-composite-deck","name":"Wood-Plastic Composite Decking Board","description":"WPC decking allowance for balconies, roof decks, and outdoor lounge areas; confirm board profile, clips, subframe, UV warranty, and drainage.","category":"Hardscape","categoryNodeId":"landscape-hardscape","supplier":"Wilcon Depot / PH outdoor decking suppliers","supplierKey":"wilcon-depot-ph-outdoor-decking-suppliers","kind":"material","unit":"sqm","unitCost":3600,"miscCost":900,"pricingSource":"Philippine WPC decking supplier allowance — verify system quote","pricingDate":"2026-05-18","confidence":"Demo seed","thumbnailPath":"/component-thumbnails/lib-wood-plastic-composite-deck.jpg","metadata":{"seeded":true,"seedVersion":"2026-05-22-component-library-taxonomy-source","sourceFixtureId":"lib-wood-plastic-composite-deck","source":"supplier","categoryNodeId":"landscape-hardscape","categoryPath":["Site","Landscape","Hardscape"],"supplierKey":"wilcon-depot-ph-outdoor-decking-suppliers","tags":["flooring","decking","wpc","outdoor"],"discipline":"Architectural","designation":"Floor / Deck Finish","sourceUrl":"https://www.wilcon.com.ph/","notes":null,"imageUrl":"/component-thumbnails/lib-wood-plastic-composite-deck.jpg"}}]'::jsonb) as item(
    id uuid,
    "originalId" text,
    "sourceId" text,
    name text,
    description text,
    category text,
    "categoryNodeId" text,
    supplier text,
    "supplierKey" text,
    kind public.cost_library_item_kind,
    unit text,
    "unitCost" numeric,
    "miscCost" numeric,
    "pricingSource" text,
    "pricingDate" date,
    confidence text,
    "thumbnailPath" text,
    metadata jsonb
  )
)
insert into public.cost_library_items (
  id,
  workspace_id,
  kind,
  name,
  description,
  category,
  category_node_id,
  supplier,
  supplier_id,
  unit,
  unit_cost,
  misc_cost,
  pricing_source,
  pricing_date,
  confidence,
  thumbnail_path,
  metadata
)
select item.id,
  w.id,
  item.kind,
  item.name,
  item.description,
  item.category,
  item."categoryNodeId",
  item.supplier,
  supplier.id,
  item.unit,
  item."unitCost",
  item."miscCost",
  item."pricingSource",
  item."pricingDate",
  item.confidence,
  item."thumbnailPath",
  item.metadata
from public.workspaces w
cross join seed_items item
join public.component_suppliers supplier
  on supplier.workspace_id = w.id
 and supplier.normalized_name = item."supplierKey"
on conflict (id) do update
  set kind = excluded.kind,
      name = excluded.name,
      description = excluded.description,
      category = excluded.category,
      category_node_id = excluded.category_node_id,
      supplier = excluded.supplier,
      supplier_id = excluded.supplier_id,
      unit = excluded.unit,
      unit_cost = excluded.unit_cost,
      misc_cost = excluded.misc_cost,
      pricing_source = excluded.pricing_source,
      pricing_date = excluded.pricing_date,
      confidence = excluded.confidence,
      thumbnail_path = excluded.thumbnail_path,
      metadata = public.cost_library_items.metadata || excluded.metadata;

update public.cost_library_items cli
set category_node_id = case
    when cli.name ilike '%general requirements%' then 'project-requirements-general-requirements'
    when cli.name ilike '%footing%' or cli.name ilike '%tie beam%' then 'foundations-footings'
    when cli.name ilike '%paint%' then 'paint-interior-paint'
    when cli.name ilike '%tile%' then 'floor-finishes-tile-flooring'
    else cli.category_node_id
  end,
  category = coalesce((
    select label
    from public.component_category_nodes c
    where c.id = case
      when cli.name ilike '%general requirements%' then 'project-requirements-general-requirements'
      when cli.name ilike '%footing%' or cli.name ilike '%tie beam%' then 'foundations-footings'
      when cli.name ilike '%paint%' then 'paint-interior-paint'
      when cli.name ilike '%tile%' then 'floor-finishes-tile-flooring'
      else cli.category_node_id
    end
  ), cli.category),
  supplier_id = supplier.id,
  supplier = coalesce(nullif(trim(cli.supplier), ''), supplier.name),
  metadata = cli.metadata || jsonb_build_object(
    'categoryNodeId', case
      when cli.name ilike '%general requirements%' then 'project-requirements-general-requirements'
      when cli.name ilike '%footing%' or cli.name ilike '%tie beam%' then 'foundations-footings'
      when cli.name ilike '%paint%' then 'paint-interior-paint'
      when cli.name ilike '%tile%' then 'floor-finishes-tile-flooring'
      else cli.category_node_id
    end,
    'seedVersion', '2026-05-22-component-library-taxonomy-source'
  )
from public.component_suppliers supplier
where supplier.workspace_id = cli.workspace_id
  and supplier.normalized_name = coalesce(nullif(regexp_replace(lower(trim(cli.supplier)), '[^a-z0-9]+', '-', 'g'), ''), 'manual-no-supplier');

with row_targets as (
  select eri.id,
    p.workspace_id,
    case
      when eri.material = 'Drag or add a component here' then 'project-requirements-general-requirements'
      when eri.material ilike '%wardrobe%' then 'casework-storage-systems'
      when eri.material ilike '%outlet%' then 'electrical-devices-receptacles'
      when eri.material ilike '%tile%' then 'floor-finishes-tile-flooring'
      when eri.material ilike '%paint%' then 'paint-interior-paint'
      else coalesce(eri.category_node_id, 'project-requirements-general-requirements')
    end as category_node_id,
    coalesce(nullif(trim(eri.supplier), ''), 'Manual / no supplier') as supplier_name,
    coalesce(nullif(regexp_replace(lower(trim(eri.supplier)), '[^a-z0-9]+', '-', 'g'), ''), 'manual-no-supplier') as supplier_key
  from public.estimate_row_items eri
  join public.estimates e on e.id = eri.estimate_id
  join public.projects p on p.id = e.project_id
)
update public.estimate_row_items eri
set category_node_id = row_targets.category_node_id,
  supplier_id = supplier.id,
  supplier = row_targets.supplier_name,
  source_snapshot = coalesce(eri.source_snapshot, '{}'::jsonb)
    || jsonb_build_object(
      'category', category.label,
      'categoryNodeId', row_targets.category_node_id,
      'supplier', row_targets.supplier_name,
      'supplierId', supplier.id,
      'taxonomyVersion', '2026-05-22-draft-3'
    ),
  metadata = eri.metadata || jsonb_build_object(
    'categoryNodeId', row_targets.category_node_id,
    'supplierId', supplier.id,
    'classificationUpdatedAt', '2026-05-22T00:00:00Z',
    'classificationSource', '2026-05-22-component-library-taxonomy-source'
  )
from row_targets
join public.component_category_nodes category on category.id = row_targets.category_node_id
join public.component_suppliers supplier
  on supplier.workspace_id = row_targets.workspace_id
 and supplier.normalized_name = row_targets.supplier_key
where eri.id = row_targets.id;

update public.estimate_row_items eri
set source_library_item_id = cli.id,
    link_state = case when eri.material = 'Drag or add a component here' then eri.link_state else 'linked-clean'::public.estimate_row_link_state end
from public.cost_library_items cli
where eri.source_library_item_id is null
  and eri.material = cli.name;
